async function place(save, refund) {
  try {
    await save();
  } catch (saveError) {
    try {
      await refund();
    } catch (refundError) {
      throw new AggregateError([saveError, refundError], "manual action needed");
    }
    throw new Error("not saved; refunded", { cause: saveError });
  }
}
