questions.solution:
function validateLines(lines) {
  const problems = lines
    .filter((line) => !Number.isInteger(line.qty) || line.qty < 1)
    .map((line) => new Error(`${line.sku}: bad quantity ${line.qty}`));
  if (problems.length > 0) throw new AggregateError(problems, `${problems.length} lines are invalid`);
  return lines;
}

try {
  validateLines([{ sku: "RICE-5", qty: 2 }, { sku: "OIL-1", qty: 0 }, { sku: "SALT", qty: 1.5 }]);
} catch (error) {
  console.log(error.message);
  for (const e of error.errors) console.log(" ", e.message);
}
console.log(validateLines([{ sku: "RICE-5", qty: 1 }]).length);

