function runJobs(jobs, handler) {
  const summary = { done: 0, failed: 0 };
  for (const job of jobs) {
    try {
      handler(job);
      summary.done += 1;
      console.log(`ok ${job.id}`);
    } catch (error) {
      summary.failed += 1;
      console.log(`failed ${job.id}: ${error.message}`);
    }
  }
  return summary;
}

const summary = runJobs([{ id: 1, to: "ada@shop.ng" }, { id: 2, to: null }, { id: 3, to: "tunde@shop.ng" }], (job) => job.to.toLowerCase());
